{
  "steps": [
    {
      "action": "Inventory the authorized fixture's binary structure and analysis prerequisites, recording format, architecture, entrypoints, sections, imports, exports, symbols, strings, protections, and analysis blockers before deeper reasoning.",
      "technique": "RE-BINARY-INVENTORY",
      "check": "The analyzed artifact hash matches campaign metadata; binary format and architecture are recorded; expected inventory artifacts exist and parse successfully; missing or malformed inputs are reported as incomplete rather than absence."
    },
    {
      "action": "Map static call relationships around the fixture's input surface, identifying entrypoints, callers, callees, indirect-call uncertainty, and data-flow-relevant helpers that participate in input handling.",
      "technique": "RE-STATIC-CALLGRAPH",
      "check": "Every claimed call edge has an address or symbol locator; unresolved indirect calls are listed explicitly; the call graph identifies which paths are proven and which remain candidates."
    },
    {
      "action": "Recover the input-validation logic by tracing input acquisition through parsing, transformations, comparisons, branch decisions, success paths, and rejection paths, and document the accepted input format, constraints, and validation constants without assuming semantics from strings alone.",
      "technique": "RE-INPUT-VALIDATION-TRACE",
      "check": "The input source and destination representation are identified; every success and rejection branch has a code locator; transformations and comparison constants are supported by decompilation or disassembly evidence; unknown helper behavior is represented as an unresolved dependency."
    },
    {
      "action": "Confirm the static hypothesis on input-validation behavior using an authorized local debugger or instrumentation probe on the authorized fixture, with explicit readiness, trigger, timeout, and hit requirements correlating runtime observations to the recovered validation branches.",
      "technique": "RE-BOUNDED-RUNTIME-CONFIRMATION",
      "check": "Runtime execution is authorized by campaign scope; the sensor or breakpoint is proven ready before interpreting hits or zero hits; the trigger window and timeout are bounded and recorded; runtime identity is correlated to the same binary hash and module as static evidence."
    }
  ]
}
